// ================================================================
//  Tsubosaka-dera (壺阪寺), le temple du Kannon des yeux, à Takatori, dans la préfecture de Nara (2026-11-05 : le treizième lieu
//  de la balade, choisi par le propriétaire : « Prochain lieu que tu vas faire c'est Tsubosaka-dera », puis, parmi mes quatre
//  propositions, « secret 1, vêtement 1 »). Son vrai nom : 壺阪山 南法華寺. La 6e étape du pèlerinage des 33 temples de l'ouest
//  du Japon (西国三十三所). D'après le temple (tsubosaka1300.or.jp) : en 703, le moine Benki (弁基), du Gangō-ji, a posé son pot de
//  cristal (水晶の壺) dans sa cabane en haut de la pente, puis il a sculpté le Kannon qui lui était apparu ; Sei Shōnagon cite le
//  temple en premier dans ses Notes de chevet (« 寺は壷坂、笠置、法輪… ») ; son Kannon aux onze visages et aux mille bras soigne
//  les yeux (眼病封じ). Au début de l'ère Meiji, un drame de marionnettes, le 壺坂霊験記 : Sawaichi (沢市), aveugle, joueur de koto et
//  de shamisen, et sa femme Osato (お里), qui monte prier chaque matin à 4 h pendant trois ans pour ses yeux ; le Kannon finit par
//  les sauver tous les deux et lui rend la vue. En 1961, le premier foyer du Japon pour les aveugles âgés (慈母園) ; depuis 1964,
//  l'aide aux malades de la lèpre en Inde : de là, les statues géantes taillées en Inde (天竺渡来), à Karkala, par des dizaines de
//  milliers de tailleurs de pierre : le grand Kannon debout (20 m, 1983, en 66 morceaux), la fresque de la vie du Bouddha (50 m,
//  1987), le Bouddha couché (8 m, 1999), le grand Bouddha assis (10 m sur un socle de 5 m, 2007, avec Monju, Fugen et un Kannon).
//  Le TikTok du propriétaire : le grand Bouddha assis parmi les cerisiers, ses statues, la pagode rouge, le grand Kannon debout,
//  des ombrelles japonaises éclairées la nuit, la fresque, les érables rouges, des hortensias et de petits jizō à bavoir rouge.
//  Son secret : les visages des 500 rakan (五百羅漢), sculptés dans les rochers de la forêt, au-dessus du temple (奥の院) : partout au
//  Japon, on dit qu'on y trouve toujours le visage de quelqu'un qu'on aime (un dicton, pas une légende du temple) ; on y cherche
//  celui de son compagnon, celui qui porte son chapeau, puis le sien. Sa récompense : le shamisen de Sawaichi (tenues.js).
//  Les hauteurs sont les vraies (GSI, le modèle à 5 m, moins 290 m) : la terrasse du bas (le parking, 293 m), celle du grand
//  Bouddha (303 m), celle du pavillon octogonal (315 m) ; la colline du grand Kannon au sud, le vallon au nord-est. Les
//  distances sont les vraies autour du temple ; le sentier des rakan est resserré.
//  Repère : x vers l'est, z vers le sud, y vers le haut, en mètres (y = l'altitude − 290 m) ; l'origine : 34,42620 N, 135,81020 E.
//  ctx : { THREE, atelier, P (palette), peinture, perso, maillage }.
// ================================================================
import { creerMonde, interactionsBancs, lisse, hasard, bruitDoux, surLaLigne } from './monde.js';
import { panneau, PAPIER_PANNEAU } from './decor.js';
import { MATIERES as M } from './textures.js';
import { secretTrouve, indiceVu } from './tresors.js';
import { nio } from './sanjubutsu.js';

const PI = Math.PI;
const melange = (a, b, t) => a + (b - a) * t;
const Y0 = 290;

// ---------------------------------------------------------------- Les vraies hauteurs (GSI dem5a ; Int16 de (h − 300) × 10, en base64)
const DEM_FIN = { x0: -240, z0: -220, pas: 4, nx: 121, nz: 111, b: '' };
const DEM_LARGE = { x0: -700, z0: -700, pas: 20, nx: 71, nz: 71, b: '' };
let VF = null, VL = null;
function lireTable(T) {
  const s = atob(T.b), n = s.length >> 1, v = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    let q = s.charCodeAt(2 * i) | (s.charCodeAt(2 * i + 1) << 8);
    if (q >= 32768) q -= 65536;
    v[i] = q / 10 + 300 - Y0;
  }
  return v;
}
function lireDans(T, V, x, z) {
  const fx = Math.min(T.nx - 1.0001, Math.max(0, (x - T.x0) / T.pas)), fz = Math.min(T.nz - 1.0001, Math.max(0, (z - T.z0) / T.pas));
  const i = fx | 0, j = fz | 0, u = fx - i, v = fz - j, k = j * T.nx + i;
  return (V[k] * (1 - u) + V[k + 1] * u) * (1 - v) + (V[k + T.nx] * (1 - u) + V[k + T.nx + 1] * u) * v;
}
/** Le sol naturel, d'après le modèle du GSI : la table fine (4 m) autour du temple, la large (20 m) au-delà, fondues sur 24 m. */
function naturel(x, z) {
  if (!VF) { VF = lireTable(DEM_FIN); VL = lireTable(DEM_LARGE); }
  const T = DEM_FIN, bord = Math.min(x - T.x0, T.x0 + (T.nx - 1) * T.pas - x, z - T.z0, T.z0 + (T.nz - 1) * T.pas - z);
  const large = lireDans(DEM_LARGE, VL, x, z);
  if (bord <= 0) return large;
  const fin = lireDans(T, VF, x, z);
  return bord >= 24 ? fin : melange(large, fin, lisse(0, 24, bord));
}

// ---------------------------------------------------------------- Le plan
// les terrasses (y : leur dessus), séparées par des murs de pierre (石垣) ; talus : la largeur où le sol rejoint le relief
const BAS = { x0: -168, x1: -64, z0: -78, z1: 6, y: 3.0 };
const MILIEU = { x0: -47, x1: -20, z0: -62, z1: 26, y: 12.8 };
const HAUT = { x0: -6, x1: 50, z0: -84, z1: 28, y: 24.7 };
// la place du Bouddha couché, sur la colline au sud (au niveau de la terrasse haute, par un chemin) ; la terrasse du grand Kannon
const NEHAN = { x0: -52, x1: -18, z0: 38, z1: 62, y: 24.7, talus: 6 };
const KANNON = { x0: -45, x1: -25, z0: 78, z1: 93, y: 34.0, talus: 7 };
const TERRASSES = [BAS, MILIEU, HAUT, NEHAN, KANNON];
// les escaliers : du bas au milieu (sous la porte des Niō) ; du milieu au haut ; de la place du Bouddha couché au grand Kannon
const ESC1 = { x0: -64, x1: -47, z0: -36, z1: -28, h0: BAS.y, h1: MILIEU.y, axe: 'x' };
const ESC2 = { x0: -20, x1: -2, z0: -27, z1: -21, h0: MILIEU.y, h1: HAUT.y, axe: 'x' };
const ESC3 = { x0: -38, x1: -32, z0: 62, z1: 78, h0: NEHAN.y, h1: KANNON.y, axe: 'z' };
const ESCALIERS = [ESC1, ESC2, ESC3];
for (const E of ESCALIERS) { E.n = Math.round((E.h1 - E.h0) / 0.18); E.long = E.axe === 'x' ? E.x1 - E.x0 : E.z1 - E.z0; }
// le chemin de la terrasse haute à la place du Bouddha couché : à plat, le long de la colline (du bord ouest de l'une au bord est de l'autre)
const LIEN = [[-5.4, 22], [-10, 28], [-15, 34.4], [-18.6, 40.6]];
const DEMI_LIEN = 1.8;
// le sentier des rakan (奥の院) : du coin sud-est de la terrasse haute, il monte dans la forêt vers le sud-est
const SENTIER = [[49, 26, HAUT.y], [55, 36, 27.6], [61, 46, 30.6], [69, 54, 33.6], [79, 60, 36.6], [89, 66, 39.6], [97, 74, 42.2], [101, 82, 43.4]];
const DEMI_SENTIER = 1.35;
const CLAIRIERE = { x: 103, z: 86, r: 6, y: 43.6 };

// ce qu'il y a sur les terrasses (les vraies places du temple, d'après sa photo aérienne et celle du GSI, un peu arrangées)
const DEPART = { x: -152, z: -31, cap: PI / 2 };
const BUS = { x: -160, z: -38, cap: PI / 2 };
const PARKING = { x0: -167, x1: -128, z0: -76, z1: -44 };
const ALLEE = { x0: -130, x1: -64, z0: -40, z1: -24 };
const JIBOEN = { x0: -122, x1: -74, z0: -76, z1: -60 };
const KODO = { x0: -122, x1: -90, z0: -16, z1: 4 };
const NIOMON = { x: -45.2, z: -32, l: 9.4, p: 5.0 };
const KANJODO = { x: -33, z: -51, l: 10, p: 8 };
const TAHOTO = { x: -33.5, z: -13, c: 5.4 };
const DAIBUTSU = { x: -26, z: 12, socle: 5.0, corps: 10.0 };
const KORO = { x: -38.5, z: 12 };
const RAIDO = { x0: 3, x1: 25, z0: -42, z1: -30 };
const HAKKAKU = { x: 14, z: -49.6, r: 7.0 };
const SANJU = { x: 36, z: -2, c: 5.2 };
const JIGENDO = { x: 3.5, z: 8, l: 9, p: 7 };
const MEGANE = { x: 22, z: 14 };
const OSATO = { x: 45.6, z: -64 };
// la fresque : contre le pied de la colline, au bord sud de la terrasse haute, tournée vers le nord ; la grotte de pierre à côté
const FRESQUE = { x0: -2, x1: 38, z: 27.4, h: 3.0 };
const SEKIDO = { x: 43.4, z: 27.6, l: 6.4 };
const NEHANZO = { x: -35, z: 50, l: 8 };
const KANNONZO = { x: -35, z: 86.5, h: 20 };
const MARCHAND = { x: -48.5, z: 57.5, cap: 2.25 };
const LAMPION = { x: -50.2, z: 55.6 };

// ---------------------------------------------------------------- Le sol
const TALUS = 1.3;
/** Le sol, calculé (lent) : le relief, les terrasses à plat et leurs talus, sous les escaliers, les chemins. */
function solBrut(x, z) {
  let h = naturel(x, z);
  // les chemins (posés sur le relief, en déblai ou en remblai, puis le talus : large le long du sentier, il ne passe pas dans une tranchée)
  for (const [pts, demi, talus] of [[LIEN.map(([px, pz]) => [px, pz, HAUT.y]), DEMI_LIEN + 0.4, 2.4], [SENTIER, DEMI_SENTIER + 0.35, 6.5]]) {
    const q = surLaLigne(pts, x, z);
    if (q.d < demi + talus) h = melange(q.h, h, lisse(demi, demi + talus, q.d) ** 1.4);
  }
  {
    const d = Math.hypot(x - CLAIRIERE.x, z - CLAIRIERE.z);
    if (d < CLAIRIERE.r + 3) h = melange(CLAIRIERE.y, h, lisse(CLAIRIERE.r, CLAIRIERE.r + 3, d));
  }
  // les terrasses : à plat dedans ; dehors, le relief les rejoint sur un talus étroit (le mur de pierre est devant)
  for (const T of TERRASSES) {
    const dx = Math.max(T.x0 - x, 0, x - T.x1), dz = Math.max(T.z0 - z, 0, z - T.z1), d = Math.hypot(dx, dz);
    if (d === 0) { h = T.y; break; }
    const tal = T.talus || TALUS;
    if (d < tal) h = melange(T.y, h, lisse(0, tal, d) ** (T.talus ? 1.6 : 1));
  }
  // sous les escaliers : 25 cm sous la ligne des nez des marches (les marches sont des blocs pleins) ; de chaque côté, le relief
  // rejoint leur pente sur 7 m (un escalier dans une tranchée de verdure, entre deux murs verts : 2026-11-05)
  for (const E of ESCALIERS) {
    const lat = E.axe === 'x' ? Math.max(E.z0 - z, 0, z - E.z1) : Math.max(E.x0 - x, 0, x - E.x1);
    const lon = E.axe === 'x' ? Math.max(E.x0 - x, 0, x - E.x1) : Math.max(E.z0 - z, 0, z - E.z1);
    if (lat > 7 || lon > 0.6) continue;
    const f = E.axe === 'x' ? (x - E.x0) / (E.x1 - E.x0) : (z - E.z0) / (E.z1 - E.z0);
    const y = E.h0 + (E.h1 - E.h0) * Math.min(1, Math.max(0, f)) - 0.25;
    if (lat === 0 && lon === 0) h = Math.min(h, y);
    else if (lat < 0.6) h = Math.min(h, melange(y, h, 0.5));
    else h = melange(y + 0.5, h, lisse(0.6, 7, lat));
  }
  return h;
}
// la grille du sol : 1 m sur ce qui se voit de près ; au-delà, le relief seul
const G = { x0: -184, z0: -108, nx: 312, nz: 230 };
let H = null;
function preparerSol() {
  H = new Float32Array(G.nx * G.nz);
  for (let j = 0, k = 0; j < G.nz; j++) for (let i = 0; i < G.nx; i++, k++) H[k] = solBrut(G.x0 + i, G.z0 + j);
}
/** La hauteur du sol en x, z. */
function terrain(x, z) {
  if (!H) preparerSol();
  const fx = x - G.x0, fz = z - G.z0;
  if (fx < 0 || fz < 0 || fx >= G.nx - 1 || fz >= G.nz - 1) return naturel(x, z);
  const i = fx | 0, j = fz | 0, u = fx - i, v = fz - j, k = j * G.nx + i, a = H[k], b = H[k + 1], c = H[k + G.nx], d = H[k + G.nx + 1];
  return (a + (b - a) * u) * (1 - v) + (c + (d - c) * u) * v;
}
// le fin : 2 m (les terrasses sont plates) ; le grossier : 8 m (les collines) ; là où le sol plie (un talus, un bord de chemin), des cases de 50 cm
const ETENDUE = { x0: -720, x1: 720, z0: -720, z1: 720, pas: 8, fin: { x0: -180, x1: 116, z0: -104, z1: 112, pas: 2 } };
const solDetaille = (x0, z0, x1, z1) => {
  const a = terrain(x0, z0), b = terrain(x1, z0), d = terrain(x0, z1), f = terrain(x1, z1);
  const bosse = (u, v) => Math.abs(terrain(x0 + (x1 - x0) * u, z0 + (z1 - z0) * v) - (u + v <= 1 ? a + (b - a) * u + (d - a) * v : f + (d - f) * (1 - u) + (b - f) * (1 - v)));
  return bosse(0.5, 0.5) > 0.06 || bosse(0.25, 0.25) > 0.06 || bosse(0.75, 0.25) > 0.06 || bosse(0.25, 0.75) > 0.06 || bosse(0.75, 0.75) > 0.06;
};

// ---------------------------------------------------------------- Le cadre : les terrasses, les escaliers, les chemins
const MARGE = 0.27;
const dansRect = (R, x, z, m = MARGE) => x > R.x0 + m && x < R.x1 - m && z > R.z0 + m && z < R.z1 - m;
// les ouvertures dans le bord des terrasses (vers un escalier, un chemin), qu'on traverse
const OUVERTURES = [
  { x0: ESC1.x0 - 0.5, x1: ESC1.x0 + 0.5, z0: ESC1.z0 + 0.5, z1: ESC1.z1 - 0.5 },
  { x0: ESC1.x1 - 0.5, x1: ESC1.x1 + 0.5, z0: NIOMON.z - 1.9, z1: NIOMON.z + 1.9 },
  { x0: ESC2.x0 - 0.5, x1: ESC2.x0 + 0.5, z0: ESC2.z0 + 0.5, z1: ESC2.z1 - 0.5 },
  { x0: ESC2.x1 - 4.5, x1: HAUT.x0 + 0.5, z0: ESC2.z0 + 0.5, z1: ESC2.z1 - 0.5 },
  { x0: ESC3.x0 + 0.5, x1: ESC3.x1 - 0.5, z0: ESC3.z0 - 0.5, z1: ESC3.z0 + 0.5 },
  { x0: ESC3.x0 + 0.5, x1: ESC3.x1 - 0.5, z0: ESC3.z1 - 0.5, z1: ESC3.z1 + 0.5 },
];
/** Peut-on être là ? Le voyageur, un point, s'arrête 27 cm avant ce qui est dessiné (les murets, les murs de pierre). */
function dansLeCadre(x, z) {
  for (const T of TERRASSES) if (dansRect(T, x, z)) return true;
  for (const E of ESCALIERS) if (x > E.x0 && x < E.x1 && z > E.z0 + 0.45 && z < E.z1 - 0.45 && E.axe === 'x') return true;
  if (x > ESC3.x0 + 0.45 && x < ESC3.x1 - 0.45 && z > ESC3.z0 && z < ESC3.z1) return true;
  for (const O of OUVERTURES) if (x > O.x0 && x < O.x1 && z > O.z0 && z < O.z1) return true;
  if (surLaLigne(LIEN, x, z).d < DEMI_LIEN - MARGE && x < HAUT.x0 + 0.4 && x > NEHAN.x1 - 0.4) return true;
  if (surLaLigne(SENTIER, x, z).d < DEMI_SENTIER - MARGE && x > HAUT.x1 - 0.4) return true;
  return Math.hypot(x - CLAIRIERE.x, z - CLAIRIERE.z) < CLAIRIERE.r - MARGE;
}
const dansLeCadreLarge = (x, z) => x > -172 && x < 110 && z > -90 && z < 100;

// ---------------------------------------------------------------- Le sol, sa couleur
/** Le sol (sa couleur et sa matière, textures.js) en x, z, à la hauteur h. */
function aspectSol(P, x, z, h) {
  const b = bruitDoux(x, z, 3);
  // le parking et la route du bus : l'asphalte
  if (x < PARKING.x1 && z > PARKING.z0 && z < PARKING.z1 && x > BAS.x0 - 0.1) return [b > 0.5 ? '#5f5e5c' : '#595856', M.route];
  if (x < BAS.x0 + 0.5 && z > -40 && z < -22) return [b > 0.5 ? '#5f5e5c' : '#595856', M.route];
  // les allées de dalles de pierre
  if (dansRect(ALLEE, x, z, 0) || (Math.abs(z - NIOMON.z) < 2.2 && x > MILIEU.x0 - 0.1 && x < -36)) return [b > 0.5 ? '#aca89e' : '#a6a297', M.dalles];
  for (const T of TERRASSES) {
    if (!dansRect(T, x, z, -0.05)) continue;
    // devant le grand Bouddha, la place dallée ; dans la cour du pavillon octogonal, des dalles au milieu, le gravier blanc autour
    if (T === MILIEU && x < -30 && z > -2 && z < 26) return [b > 0.5 ? '#b2aea4' : '#aaa69b', M.dalles];
    if (T === HAUT && Math.abs(x - HAKKAKU.x) < 2.1 && z > RAIDO.z1 && z < 22) return [b > 0.5 ? '#aca89e' : '#a6a297', M.dalles];
    if (T === NEHAN || T === KANNON) return [b > 0.5 ? '#b0aca2' : '#a9a59a', M.dalles];
    // le gravier, un peu plus sombre au pied des murs ; la mousse par taches à l'ombre des arbres
    const bord = Math.min(x - T.x0, T.x1 - x, z - T.z0, T.z1 - z);
    if (bord < 1.6 && bruitDoux(x + 9, z - 4, 1.7) > 0.45) return [b > 0.5 ? '#6f7d4e' : '#667548', M.mousse];
    return [bruitDoux(x, z, 1.3) > 0.5 ? '#c9c4b6' : '#c2bdae', M.terre];
  }
  // les marches (sous elles, rien ne se voit), les chemins de terre de la forêt
  if (surLaLigne(SENTIER, x, z).d < DEMI_SENTIER + 0.2 || Math.hypot(x - CLAIRIERE.x, z - CLAIRIERE.z) < CLAIRIERE.r + 0.2) return [b > 0.5 ? '#7a6a52' : '#71624c', M.terre];
  if (surLaLigne(LIEN, x, z).d < DEMI_LIEN + 0.2) return [b > 0.5 ? '#aca89e' : '#a6a297', M.dalles];
  // les talus (sous les murs de pierre) ; la forêt : son sol de feuilles, de mousse et de fougères
  return [b > 0.55 ? '#46613b' : '#4f6a40', M.sousBois];
}

