    a.ovale(0.075 * k, G, { ...o(u * 0.045, 0.22, 0.22), sx: 1.1, sy: 0.38, sz: 0.85 }, 10)
      .ovale(0.022 * k, G, { ...o(u * 0.018, 0.26, 0.255), sx: 0.8, sy: 1.6, sz: 0.8, rz: u * 0.5 }, 6);
