  // le col de la robe : un pan croisé sur la poitrine
  a.ovale(0.17 * k, GF, { ...o(-0.03, 0.55, 0.11), sx: 0.75, sy: 0.32, sz: 0.25, rz: 0.55 }, 10);
  // le cou et ses trois plis (三道)
  a.cylindre(0.072 * k, 0.085 * k, 0.09 * k, 14, G, o(0, 0.7, 0));
