  // la tête : le visage un peu allongé, les joues pleines ; les yeux mi-clos, les sourcils en arc, le nez, la bouche, la marque
  a.ovale(0.12 * k, G, { ...o(0, 0.83, 0.02), sx: 0.93, sy: 1.08, sz: 0.95 }, f);
