        for (let c = 0; c < 4; c++) {
          const ry = (c * PI) / 2, cr = Math.cos(ry), sr = Math.sin(ry);
          const pose = (lx, ly, lz, o = {}) => W(lx * cr + lz * sr, ly, -lx * sr + lz * cr, { ry, ...o }), q = c % 2 ? 0.012 : 0;
          a.boite(lb, 0.07, 0.07, VERM, pose(0, yb + 0.62 + q, lb / 2 - 0.03)).boite(lb, 0.05, 0.05, VERM, { ...pose(0, yb + 0.3 + q, lb / 2 - 0.03), trait: false });
          for (let j = 0; j <= 6; j++) a.boite(0.07, 0.66 + q, 0.07, VERM, pose(-lb / 2 + 0.07 + (j * (lb - 0.14)) / 6, yb + 0.33 + q / 2, lb / 2 - 0.03 + (j % 2 ? 0.004 : 0)));
        }
