      if (n % 3 === 1) { jizo(THREE, a, repere(x + 0.75, z + 0.4, PI / 2), y, 0.62, (s) => tachee(s, 0.15)); monde.cercle(x + 0.75, z + 0.4, 0.3); }
      if (n % 4 === 2) ombrelle(a, x - 0.1, z + 0.9, y, OMBRELLES[n % OMBRELLES.length], 0.3, PI / 2 + (hasard(n, 2) - 0.5), 1.15);
